mapper.select:
SELECT p.task_id AS taskId, p.lng, p.lat, p.observed_at AS observedAt FROM ( SELECT e.task_id, CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload, '$.payload.lng')) AS DECIMAL(10, 6)) AS lng, CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload, '$.payload.lat')) AS DECIMAL(10, 6)) AS lat, e.observed_at, ROW_NUMBER() OVER (PARTITION BY e.task_id ORDER BY e.id DESC) AS rn FROM task_evidence e WHERE e.task_id IN
#{taskId}
AND ) p WHERE p.rn = 1

SELECT t.task_id AS taskId, t.lng, t.lat, t.observed_at AS observedAt FROM ( SELECT e.task_id, CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload, '$.payload.lng')) AS DECIMAL(10, 6)) AS lng, CAST(JSON_UNQUOTE(JSON_EXTRACT(e.payload, '$.payload.lat')) AS DECIMAL(10, 6)) AS lat, e.observed_at, ROW_NUMBER() OVER (PARTITION BY e.task_id ORDER BY e.id DESC) AS rn FROM task_evidence e WHERE e.task_id IN
#{taskId}
AND ) t WHERE t.rn <= #{perTaskLimit} ORDER BY t.task_id, t.rn DESC

SELECT COUNT(*)
FROM task_evidence e
WHERE e.observed_at >= #{from}

SELECT COUNT(DISTINCT e.device_code)
FROM task_evidence e
WHERE e.observed_at >= #{from}
